#include <cstddef>
#include <string>
#include <vector>

// One type parameter per independent argument: the needle never has to be
// converted at the call site just to make deduction agree.
template<class Range, class Needle>
std::size_t count_equal(const Range& values, const Needle& needle) {
    std::size_t hits = 0;
    for (const auto& value : values) {
        if (value == needle) ++hits;
    }
    return hits;
}

// A single parameter forces both arguments to propose the same type.
template<class T>
std::size_t count_exact(const std::vector<T>& values, const T& needle) {
    return count_equal(values, needle);
}

std::size_t demo() {
    std::vector<std::string> words{"the", "cat", "the"};

    // Deduction never converts to reconcile proposals, so count_exact(words,
    // "the") is an error: std::string vs const char*. Two forms that work:
    std::size_t a = count_exact(words, std::string{"the"});  // convert the argument
    std::size_t b = count_exact<std::string>(words, "the");  // fix T explicitly

    // count_equal gives the needle its own parameter, so the literal keeps its
    // own type and std::string's operator==(const char*) does the comparison.
    std::size_t c = count_equal(words, "the");

    return a + b + c;
}

