#include <cstddef>
#include <map>
#include <string>
#include <type_traits>

// Alias template: a name for a family of types, not a new type.
template<class Key>
using Counts = std::map<Key, std::size_t>;

static_assert(std::is_same_v<Counts<std::string>, std::map<std::string, std::size_t>>);

// Variable template: one constant per type.
template<class T>
constexpr T zero = T{};

// Class template: its argument is spelled at the use site, because ordinary
// function-template deduction does not apply to a class.
template<class Key>
class Histogram {
public:
    void add(const Key& key) { ++counts_[key]; }

    std::size_t count(const Key& key) const {
        auto found = counts_.find(key);
        return found == counts_.end() ? zero<std::size_t> : found->second;
    }

    const Counts<Key>& buckets() const { return counts_; }

private:
    Counts<Key> counts_{};
};

// Function template: Key is deduced from the argument.
template<class Key>
std::size_t total(const Histogram<Key>& histogram) {
    std::size_t sum = 0;
    for (const auto& bucket : histogram.buckets()) sum += bucket.second;
    return sum;
}

std::size_t demo() {
    Histogram<std::string> words;   // spelled
    words.add("fig");
    words.add("fig");
    words.add("pear");

    return total(words)             // deduced
         + words.count("fig")
         + words.count("absent");   // zero<std::size_t>
}

