#include <concepts>
#include <cstddef>
#include <string>
#include <vector>

// A requires expression states which expressions must be well-formed and what
// their results must convert to. Nothing in it is ever evaluated.
template<class T>
concept Sized = requires(const T& value) {
    { value.size() } -> std::convertible_to<std::size_t>;
    { value.empty() } -> std::convertible_to<bool>;
};

static_assert(Sized<std::string>);
static_assert(Sized<std::vector<int>>);
static_assert(!Sized<int>);

// Constrained template parameter.
template<Sized T>
bool same_length(const T& left, const T& right) {
    return left.size() == right.size();
}

// The same constraint written as a requires clause.
template<class T>
    requires Sized<T>
std::size_t widest(const std::vector<T>& items) {
    std::size_t best = 0;
    for (const T& item : items) {
        if (!item.empty() && item.size() > best) best = item.size();
    }
    return best;
}

// Abbreviated form.
bool blank(const Sized auto& value) { return value.empty(); }

std::size_t demo() {
    std::vector<std::string> rows{"fig", "banana"};

    // same_length(1, 2) is rejected at the call site: int has no .size().
    // Every one of these constraints is a compile-time question only; the
    // generated code is identical to the unconstrained version.
    return widest(rows)
         + static_cast<std::size_t>(same_length(rows[0], rows[0]))
         + static_cast<std::size_t>(blank(rows));
}

