#include <cstddef>
#include <string>
#include <vector>

// The predicate is a template parameter, so its concrete type reaches this
// loop body and can be inlined. No std::function, no indirect call.
template<class Range, class Pred>
std::size_t count_if_manual(const Range& range, Pred pred) {
    std::size_t hits = 0;
    for (const auto& item : range) {
        if (pred(item)) ++hits;
    }
    return hits;
}

// What the compiler generates for a lambda capturing one std::size_t by value:
// one data member per capture, and a const call operator.
struct LongEnough {
    std::size_t minimum;

    bool operator()(const std::string& word) const { return word.size() >= minimum; }
};

bool demo() {
    std::vector<std::string> words{"a", "cat", "hippo"};
    std::size_t minimum = 3;

    // The closure type is unique and unnamed, so auto is the only spelling.
    auto long_enough = [minimum](const std::string& word) {
        return word.size() >= minimum;
    };

    static_assert(sizeof(long_enough) == sizeof(std::size_t));

    return count_if_manual(words, long_enough)
        == count_if_manual(words, LongEnough{minimum});
}

