#include <cstddef>
#include <string>
#include <vector>

// BROKEN: pattern dies with the call, and a reference capture never extends a
// lifetime, so every later match reads a destroyed string -- undefined
// behaviour, not merely a wasted copy avoided.
//
//   auto make_matcher(const std::string& pattern) {
//       return [&pattern](const std::string& line) {
//           return line.find(pattern) != std::string::npos;
//       };
//   }

// Returned, so it must own everything it needs: capture by value.
auto make_matcher(std::string pattern) {
    return [pattern](const std::string& line) {
        return line.find(pattern) != std::string::npos;
    };
}

// Consumed inside this call only, and both referents outlive it, so a
// reference capture is safe here and keeps the closure to two pointers.
std::size_t count_matches(const std::vector<std::string>& lines,
                          const std::string& pattern) {
    std::size_t hits = 0;
    auto tally = [&](const std::string& line) {
        if (line.find(pattern) != std::string::npos) ++hits;
    };

    for (const std::string& line : lines) tally(line);
    return hits;
}

std::size_t demo() {
    std::vector<std::string> lines{"GET /home", "GET /help", "POST /home"};

    auto is_home = make_matcher("/home");   // outlives the string it was built from
    std::size_t direct = count_matches(lines, "/home");

    std::size_t stored = 0;
    for (const std::string& line : lines) stored += is_home(line);
    return direct + stored;
}

