#include <algorithm>
#include <string>
#include <vector>

// The projection is a template parameter, so its concrete type -- and with it
// its body -- is visible inside this instantiation and inside the std::sort
// instantiation it drives. The comparator captures it by reference, so the
// projection object is not copied once per comparison.
template<class Range, class Project>
void sort_by(Range& range, Project project) {
    std::sort(range.begin(), range.end(),
              [&project](const auto& left, const auto& right) {
                  return project(left) < project(right);
              });
}

struct Session {
    std::string user;
    int seconds;
};

void demo() {
    std::vector<std::string> words{"banana", "fig", "pear"};
    std::vector<std::vector<int>> rows{{1, 2, 3}, {4}, {5, 6}};
    std::vector<Session> sessions{{"ana", 30}, {"bo", 12}};

    // One closure object, two instantiations of its templated operator().
    auto by_size = [](const auto& value) { return value.size(); };

    sort_by(words, by_size);
    sort_by(rows, by_size);
    sort_by(sessions, [](const Session& session) { return session.seconds; });

    // sort_by(sessions, by_size) would not compile: Session has no .size().
    // A generic lambda is still only valid for types supporting what it uses.
}
